<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Authentication\Application\TokenGranter;

use Civi\Lughauth\Features\Oidc\Authentication\Domain\AuthenticationRequest;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\AuthenticationResult;

class TokenGranterMediator
{
    private readonly array $granters;
    public function __construct(
        ResolverForPassword $passResolver,
        ResolverForRefresh $refreshResolver,
        ResolverForDevice $deviceResolver,
        ResolverForClientCredentials $clientCredentialsResolver
    ) {
        $this->granters = [ $passResolver, $refreshResolver, $deviceResolver, $clientCredentialsResolver ];
    }

    public function authenticate(
        string $grantType,
        string $tenant,
        AuthenticationRequest $client,
        array $params
    ): ?AuthenticationResult {
        foreach ($this->granters as $granter) {
            if ($granter->canHandle($grantType, $params)) {
                return $granter->authenticate($tenant, $client, $params);
            }
        }
        return null;
    }
}
